function dhakaDate(string $v,bool $full=false):string{try{$d=new DateTimeImmutable($v);}catch(Throwable $e){$d=new DateTimeImmutable('now');}$d=$d->setTimezone(new DateTimeZone('Asia/Dhaka'));return $full?$d->format('M j, Y · g:i A'):$d->format('g:i A');}
Security::csrfToken();session_write_close();
$messages=[];$error=null;$aliasFilter=trim((string)($_GET['alias']??''));$selectedId=(int)($_GET['message']??0);$initialQuery=trim((string)($_GET['q']??''));
$inboxId=(int)($_GET['inbox']??0);
if(array_key_exists('inbox',$_GET)){
 $inbox=$inboxId>0?Database::findAlias($inboxId):null;
 if(!$inbox){http_response_code(404);exit('Address not found. Return to the inbox.');}
 $aliasFilter=(string)$inbox['email'];
}elseif($aliasFilter!=='' && ($legacyId=Database::aliasId($aliasFilter))>0){
 $params=['inbox'=>$legacyId];if($selectedId>0)$params['message']=$selectedId;if($initialQuery!=='')$params['q']=$initialQuery;
 header('Location: /?'.http_build_query($params));exit;
}
try{$s=null;MultiMailbox::synchronize();$messages=$initialQuery!==''?Database::searchMessages($initialQuery,(Database::messageLimit()>0?min(50,Database::messageLimit()):50),$aliasFilter):Database::recent((Database::messageLimit()>0?min(50,Database::messageLimit()):50),null,$aliasFilter!==''?$aliasFilter:null);}catch(Throwable $e){$error=$e->getMessage();$messages=$initialQuery!==''?Database::searchMessages($initialQuery,(Database::messageLimit()>0?min(50,Database::messageLimit()):50),$aliasFilter):Database::recent((Database::messageLimit()>0?min(50,Database::messageLimit()):50),null,$aliasFilter!==''?$aliasFilter:null);}
$selected=null;if($selectedId>0){foreach($messages as $m){if((int)$m['id']===$selectedId){$selected=$m;break;}}if(!$selected)$selected=Database::findMessage($selectedId);}if(!$selected)$selected=$messages[0]??null;
$fullMessage=null;$fullMessageError=null;
if($selected){try{
    $accountLock=MailboxRegistry::acquire((int)$selected['account_id'],true);
    $s=new MailService(true,(int)$selected['account_id']);
    $fullMessage=$s->fetchFullMessage((int)$selected['imap_uid']);
    if($s->markRead((int)$selected['imap_uid'])){
        Database::markRead((int)$selected['id']);$selected['is_read']=1;
        foreach($messages as &$mm)if((int)$mm['id']===(int)$selected['id'])$mm['is_read']=1;
        unset($mm);
    }
}catch(Throwable $e){$fullMessageError='Unable to load this message. It may have been removed from the mailbox.';}finally{MailboxRegistry::release($accountLock??null);}}
$recipientAddress=(string)(($selected['original_to']??'')?:($selected['alias_email']??''));
if($recipientAddress===''&&preg_match('/[A-Z0-9._%+\-]+@[A-Z0-9.\-]+\.[A-Z]{2,}/i',(string)($fullMessage['to']??''),$recipientMatch))$recipientAddress=$recipientMatch[0];
$displayCode=$fullMessage!==null?($fullMessage['code']??null):MailClassifier::code('verification code: '.($selected['code']??''));
$aliases=Database::aliases('new');$unread=(int)array_sum(array_map(fn($m)=>(int)$m['is_read']===0?1:0,$messages));
