etSetting('refresh_interval','0') ?>,unreadCount:<?=$unread?>,selectedId:<?=$selected?(int)$selected['id']:0?>,latestId:<?=Database::latestSelectedId()?>,viewToken:<?=json_encode(MailboxRegistry::viewToken())?>,hasAccounts:<?=MailboxRegistry::selectedIds()?'true':'false'?>,emailTheme:<?=json_encode(Database::getSetting('email_body_theme','light'))?>,messageLimit:<?=Database::messageLimit()?>,initialMessages:<?=json_encode($messages,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_INVALID_UTF8_SUBSTITUTE)?>};</script><script src="/assets/app.js?v=17"></script><?php require __DIR__.'/app/Navigation.php'; ?></body></html>
